// The ROMs built into the firmware (generated by tools/embed_roms.py from roms/).
#pragma once

#include <stdint.h>
#include <stddef.h>

struct RomBlob {
  char const *    name;     // file name in roms/
  uint8_t const * data;     // in flash, mapped through the cache
  size_t          size;
};

extern const RomBlob g_roms[];
extern const int     g_romCount;
